#include <torch/extension.h>
torch::Tensor matmul(torch::Tensor A, torch::Tensor B);
"""
gemm_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cuda_pipeline.h>
#include <cute/tensor.hpp>
using namespace cute;
// C(M,N) = A(M,K) * B(K,N), all row-major float32.
// B is viewed as (N,K) with stride (1,N) so the cute::gemm (M,K)x(N,K)->(M,N)
// "TN" form computes sum_k A(m,k) * B(k,n) exactly.
template <class TA, class TB, class TC>
__global__ static void
gemm_device(int M, int N, int K,
            TA const* __restrict__ A,
            TB const* __restrict__ B,
            TC*       __restrict__ C)
{
  // Shared-memory bank-conflict reduction: replace padded strides with an
  // XOR-swizzled float4 layout for both A and B tiles. Global loads stay
  // contiguous float4/cp.async, while logical->physical smem columns are
  // permuted per row so MMA-side reads spread across banks without padding.
  constexpr int BM = 128;
  constexpr int BN = 128;
  constexpr int BK = 16;
  constexpr int THREADS = 256;
  constexpr int STAGES = 3;
  __shared__ alignas(16) TA smemA[STAGES][BM * BK];
  __shared__ alignas(16) TB smemB[STAGES][BK * BN];
  const int cta_m = blockIdx.x * BM;
  const int cta_n = blockIdx.y * BN;
  const int K_TILE_MAX = K / BK;
  // Asynchronously stage one swizzled 128x16 A tile and one 16x128 B tile.
  auto load_stage = [&](int k_tile, int stage) {
    const int k0 = k_tile * BK;
    // A: 128x16 floats = 512 float4; 256 threads load 2 float4 each.
    #pragma unroll
    for (int i = 0; i < 2; ++i) {
      const int idx = threadIdx.x + i * THREADS;
      const int row = idx >> 2;  // 4 float4 per row
      const int c4  = idx & 3;
      const int pc4 = c4 ^ (row & 3);
      const float4* src = reinterpret_cast<const float4*>(A + (cta_m + row) * K + k0 + c4 * 4);
      float4* dst = reinterpret_cast<float4*>(smemA[stage] + row * BK + pc4 * 4);
      __pipeline_memcpy_async(dst, src, sizeof(float4));
    }
    // B row-major (K,N): 16x128 floats = 512 float4; 256 threads load 2 float4 each.
    #pragma unroll
    for (int i = 0; i < 2; ++i) {
      const int idx = threadIdx.x + i * THREADS;
      const int n4 = idx & 31; // 32 float4 across N for fixed k
      const int kk = idx >> 5;
      const int pn4 = n4 ^ kk;
      const float4* src = reinterpret_cast<const float4*>(B + (k0 + kk) * N + cta_n + n4 * 4);
      float4* dst = reinterpret_cast<float4*>(smemB[stage] + kk * BN + pn4 * 4);
      __pipeline_memcpy_async(dst, src, sizeof(float4));
    }
  };
  // Prime the 3-stage pipeline with the first two K tiles.
  load_stage(0, 0);
  __pipeline_commit();
  if (K_TILE_MAX > 1) {
    load_stage(1, 1);
    __pipeline_commit();
  }
  const int warp_id = threadIdx.x >> 5;
  const int lane    = threadIdx.x & 31;
  const int warp_m  = warp_id & 3;  // 4 warps along M, 32 rows each
  const int warp_n  = warp_id >> 2; // 2 warps along N, 64 cols each
  const int tm      = lane & 3;     // 4 row groups; rows interleaved by 4
  const int tn      = lane >> 2;    // 8 column groups of 8 contiguous cols
  const int a_row0  = warp_m * 32 + tm;
  const int b_f0    = warp_n * 16 + tn * 2; // logical float4 column of col0
  const int col0 = b_f0 << 2; // scalar column of this thread's 8-wide tile
  // Register accumulator: 8x8 per-thread micro-tile
  float acc[8][8];
  #pragma unroll
  for (int i = 0; i < 8; ++i) {
    #pragma unroll
    for (int j = 0; j < 8; ++j) {
      acc[i][j] = 0.0f;
    }
  }
  int stage = 0;
  for (int k_tile = 0; k_tile < K_TILE_MAX; ++k_tile) {
    const int prefetch = k_tile + STAGES - 1;
    if (prefetch < K_TILE_MAX) {
      load_stage(prefetch, (stage + STAGES - 1) % STAGES);
      __pipeline_commit();
    }
    const int remaining = K_TILE_MAX - 1 - k_tile;
    const int newer = remaining < (STAGES - 1) ? remaining : (STAGES - 1);
    __pipeline_wait_prior(newer);
    __syncthreads();
    const float* sA = smemA[stage];
    const float* sB = smemB[stage];
    // Vectorized shared-memory A loads: one float4 per row covers 4 kk steps,
    // reducing A smem load instructions 4x versus per-kk scalar loads.
    #pragma unroll
    for (int kg = 0; kg < (BK >> 2); ++kg) {
      const int a_g = kg ^ tm;
      float a_frag[8][4];
      #pragma unroll
      for (int i = 0; i < 8; ++i) {
        *reinterpret_cast<float4*>(a_frag[i]) =
            *reinterpret_cast<const float4*>(sA + (a_row0 + (i << 2)) * BK + (a_g << 2));
      }
      #pragma unroll
      for (int e = 0; e < 4; ++e) {
        const int kk = (kg << 2) | e;
        const int bp0 = (b_f0 ^ kk) << 2;
        const int bp1 = ((b_f0 + 1) ^ kk) << 2;
        const float4 b0 = *reinterpret_cast<const float4*>(sB + kk * BN + bp0);
        const float4 b1 = *reinterpret_cast<const float4*>(sB + kk * BN + bp1);
        #pragma unroll
        for (int i = 0; i < 8; ++i) {
          const float a = a_frag[i][e];
          acc[i][0] = fmaf(a, b0.x, acc[i][0]);
          acc[i][1] = fmaf(a, b0.y, acc[i][1]);
          acc[i][2] = fmaf(a, b0.z, acc[i][2]);
          acc[i][3] = fmaf(a, b0.w, acc[i][3]);
          acc[i][4] = fmaf(a, b1.x, acc[i][4]);
          acc[i][5] = fmaf(a, b1.y, acc[i][5]);
          acc[i][6] = fmaf(a, b1.z, acc[i][6]);
          acc[i][7] = fmaf(a, b1.w, acc[i][7]);
        }
      }
    }
    __syncthreads();
    stage = (stage + 1) % STAGES;
  }
  // Epilogue: vectorized float4 stores of the 8x8 register tile
  #pragma unroll
  for (int i = 0; i < 8; ++i) {
    const int gm = cta_m + warp_m * 32 + i * 4 + tm;
    float* out = C + gm * N + cta_n + col0;
    *reinterpret_cast<float4*>(out)     = make_float4(acc[i][0], acc[i][1], acc[i][2], acc[i][3]);
    *reinterpret_cast<float4*>(out + 4) = make_float4(acc[i][4], acc[i][5], acc[i][6], acc[i][7]);
  }
}
torch::Tensor matmul(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "Expect float32 tensors");
  int M = (int)A.size(0);
  int K = (int)A.size(1);
  int N = (int)B.size(1);
